using UnityEngine;

namespace AiOn.People
{
    /// <summary>
    /// Drives one of the original's baked people (Art/People/person-*.glb). Animation names are the original's:
    /// idle, walk, brisk, run (one blend space by speed), carry, walker, sit, sitChair, talk, phone, wave, point, crouch,
    /// stairsUp, stairsDown, hurt, down, air; one-shot clips: punch, throw, pickup, vault, climb, land, hurt.
    /// The Animator controller is generated by AiOn → Build People (states named after the clips, a "Locomotion"
    /// blend tree on the float "Speed").
    /// </summary>
    [RequireComponent(typeof(Animator))]
    public class PersonAnimator : MonoBehaviour
    {
        public const float WalkSpeed = 1.3f, BriskSpeed = 2.1f, RunSpeed = 3.9f;
        public const float Fade = 0.2f;
        /// <summary>Seconds of offset a full phase gives on a cross-fade (about one gait cycle of the baked clips).</summary>
        const float CycleSeconds = 1.1f;

        public string preset;
        [Tooltip("Animation shown when the scene starts.")]
        public string startAnim = "idle";
        [Tooltip("Cycle offset (0..1) when an animation starts, so people of a crowd do not move in lockstep (people.js seed phase).")]
        [Range(0, 1)] public float phase;

        Animator _animator;
        string _current;
        static readonly int SpeedId = Animator.StringToHash("Speed");

        public string Current => _current;

        void Awake()
        {
            _animator = GetComponent<Animator>();
            _animator.applyRootMotion = false;
            _animator.cullingMode = AnimatorCullingMode.CullUpdateTransforms;
        }

        void OnEnable() { _current = null; SetAnim(startAnim, instant: true); }

        static bool IsGait(string name) => name == "walk" || name == "brisk" || name == "run";

        /// <summary>Switches the looping animation. Gaits take a speed in m/s (default: the gait's own speed).</summary>
        public void SetAnim(string name, float? speed = null, bool instant = false)
        {
            if (string.IsNullOrEmpty(name) || !_animator || !_animator.runtimeAnimatorController) return;
            if (IsGait(name))
            {
                _animator.SetFloat(SpeedId, speed ?? (name == "walk" ? WalkSpeed : name == "brisk" ? BriskSpeed : RunSpeed));
                name = "Locomotion";
            }
            if (name == _current) return;
            _current = name;
            if (instant) _animator.Play(name, 0, phase);
            else _animator.CrossFadeInFixedTime(name, Fade, 0, phase * CycleSeconds);
        }

        /// <summary>Locomotion by speed alone: idle below 0.15 m/s, else the walk-brisk-run blend.</summary>
        public void Move(float speed)
        {
            if (speed < 0.15f) { SetAnim("idle"); return; }
            _animator.SetFloat(SpeedId, speed, 0.12f, Time.deltaTime);
            if (_current != "Locomotion") { _current = "Locomotion"; _animator.CrossFadeInFixedTime("Locomotion", Fade, 0, phase * CycleSeconds); }
        }

        /// <summary>Plays a one-shot clip over the current animation, then returns to it.</summary>
        public void Play(string clip)
        {
            if (!_animator || !_animator.runtimeAnimatorController) return;
            _animator.CrossFadeInFixedTime("clip_" + clip, 0.08f, 1);
        }
    }
}
